import{z as s,x as B,o as l,c as A,q as t,j as i,D as e,d as o,s as n,S as p,b as E}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"训练-推理精度不匹配","description":"","frontmatter":{"title":"训练-推理精度不匹配","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/train-infer-mismatch.md","filePath":"llm/train-infer-mismatch.md","lastUpdated":1791413859000}'),d={name:"llm/train-infer-mismatch.md"};function m(h,a,c,f,g,F){const r=B("Mermaid");return l(),A("div",null,[a[2]||(a[2]=t('<h1 id="训练-推理精度不匹配" tabindex="-1">训练-推理精度不匹配 <a class="header-anchor" href="#训练-推理精度不匹配" aria-label="Permalink to &quot;训练-推理精度不匹配&quot;">​</a></h1><div class="epigraph"><p>版本号相同、模板相同，logπ 仍可以系统性地偏：生成在 FP8 引擎里，训练在 BF16 里，比率全是噪声。</p><footer>—— 对照 OpenRLHF / verl 要求重算对数概率；推理量化与训练精度对齐的工程报告</footer></div><p><a href="/llm/rl-difficulty-curriculum">上一课</a>与温度、课程把分布对齐到「该学的题」。缺口是数值：<strong>rollouter 的量化、内核、softmax 实现与 learner 不一致时，存储的 \\(\\log\\pi_{\\mathrm{beh}}\\) 不是训练图上的 \\(\\pi\\)。</strong> 这是假 off-policy。本课写精度与内核匹配。它结束「超参与偏差」单元，下一单元转向自博弈与监督扩展。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>vLLM / SGLang 常用 FP8 / INT8 权、融合 softmax、不同的 RoPE 数值。Megatron 训练用 BF16，softmax 在 fp32 累加。逐步 \\(\\log\\pi\\) 差 \\(10^{-2}\\) 量级，长链上累积到使 \\(\\rho_t\\) 偏离 1，即使 <code>sync_id</code> 相同。</p><p><span class="marginnote">数字感受一下：单个 token 的 logπ 差 \\(10^{-2}\\)，意味着概率本身差约 1%。一条 100 步的生成链把这些差累加起来，比率 \\(\\rho\\) 整体就能偏离 \\(e \\approx 2.7\\) 倍量级——在 clip 眼里，这批 token 全都「走太远」了，尽管权重一模一样。</span></p><p><span class="marginnote">术语翻译：\\(\\rho\\)（重要性比率）= 同一批 token 在「新策略」下的概率 ÷ 在「旧策略」下的概率。正常近端更新里两者应该几乎是同一个分布，\\(\\rho\\) 在 1 附近小幅波动；它若系统性偏离 1，说明你拿去比较的其实不是同一个 \\(\\pi\\)。</span>PPO clip 会把大量 token 判为「走太远」而截掉，有效更新变稀，或反向把噪声当优势。</p><p>另一类不匹配：dropout 在训练前向开着、生成时关；或 RMSNorm 的 epsilon、词汇表裁剪不同。这些比 FP8 更隐蔽。词表里的特殊思维标签若只在一侧注册，整段链的 logprob 会从第一枚标签开始偏。</p><h3 id="重算是校正-不是可选优化" tabindex="-1">重算是校正，不是可选优化 <a class="header-anchor" href="#重算是校正-不是可选优化" aria-label="Permalink to &quot;重算是校正，不是可选优化&quot;">​</a></h3><p>正确做法：用与梯度同一张训练图、同一精度，对 \\((x,y)\\) 重算 \\(\\log\\pi_\\theta\\) 与（若需要）\\(\\log\\pi_{\\mathrm{old}}\\)。生成引擎的 logprob 只用于采样决策，不进损失——除非已证明与训练图逐 token 对齐。许多崩溃在「为省一次前向而相信引擎 logprob」之后出现。</p><p><span class="marginnote">参考模型若也走推理引擎，KL 同样偏。无 KL 配方少一条偏置源，仍要策略自身自洽。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>清单：词表与特殊 token id、chat 模板、精度、RoPE/YaRN 参数、是否融合 MoE 路由、dropout 全关、mask 一致。对齐测试：同一批 \\((x,y)\\) 在引擎与训练图上算 logprob，看最大绝对误差与 clip 命中率。</p><p><span class="marginnote">常见误区：初学者容易以为同一份权重在任何引擎里输出完全一致——实际上 FP8 与 BF16、是否融合 softmax、RoPE 的数值实现，都会让同一个 token 的概率在小数点后几位上不同。单独看无害，进了比率就是系统偏差。</span>超过阈值则强制重算，或把生成也改成训练精度（慢）。量化 rollouter 可以保留，但 IS 分母改用重算的 BF16 \\(\\pi_{\\mathrm{beh}}\\)——注意：那已经不是真行为概率，采样仍来自量化模型。更干净的是：采样与 logprob 都承认量化是 \\(\\pi_{\\mathrm{beh}}\\)，训练图用同一量化前向（难）或接受偏差并减小 \\(\\eta\\)。</p>',14)),(l(),i(p,null,{default:e(()=>[n(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20ENG%5B%22%E5%BC%95%E6%93%8E%20FP8%20log%CF%80%22%5D%20--%3E%20GAP%5B%22%E4%B8%8E%20BF16%20%E8%AE%AD%E7%BB%83%E5%9B%BE%E4%B8%8D%E4%B8%80%E8%87%B4%22%5D%0A%20%20GAP%20--%3E%20RE%5B%22%E8%AE%AD%E7%BB%83%E5%9B%BE%E9%87%8D%E7%AE%97%20log%CF%80%22%5D%0A%20%20RE%20--%3E%20RATIO%5B%22%CF%81%20%E6%89%8D%E8%BF%9B%E5%85%A5%20clip%22%5D%0A%20%20TEST%5B%22%E5%90%8C%E4%B8%80%20y%20%E5%AF%B9%E8%AF%AF%E5%B7%AE%22%5D%20--%3E%20GATE%5B%22%E8%B6%85%E9%98%88%E5%88%99%E7%A6%81%E6%AD%A2%E7%94%A8%E5%BC%95%E6%93%8E%20log%CF%80%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"种子：采样在引擎，重算是 teacher-forced，不需要同种子。需要复现轨迹时才钉引擎种子。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[o("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,[o("softmax 的实现差是乘性噪声，clip 把它变成非对称的稀疏梯度。看起来像熵塌或学习率过大，根因是比率失效。对齐后，clip 命中率应回到「真的近端更新」水平。这与 "),E("a",{href:"/llm/truncated-importance-sampling"},"截断 IS"),o(" 的 \\(c\\) 正交：先消除系统偏差，再谈截断阈值。")],-1)),(l(),i(p,null,{default:e(()=>[n(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E7%B2%BE%E5%BA%A6%E4%B8%8E%E5%86%85%E6%A0%B8%E5%B7%AE%E5%BC%82%22%5D%20--%3E%20B%5B%22%E6%AF%8F%E4%B8%AA%20token%20%E7%9A%84%20log%CF%80%20%E7%B3%BB%E7%BB%9F%E6%80%A7%E5%81%8F%E7%A7%BB%22%5D%0A%20%20B%20--%3E%20C%5B%22%E9%95%BF%E9%93%BE%E7%B4%AF%E7%A7%AF%EF%BC%9A%CF%81%20%E5%81%8F%E7%A6%BB%201%22%5D%0A%20%20C%20--%3E%20D%7B%22PPO%20clip%20%E5%A6%82%E4%BD%95%E5%A4%84%E7%BD%AE%22%7D%0A%20%20D%20--%3E%7C%22%E5%81%8F%E5%87%BA%E5%AE%89%E5%85%A8%E5%8C%BA%22%7C%20E%5B%22%E5%A4%A7%E9%87%8F%20token%20%E8%A2%AB%E5%88%A4%E8%B6%8A%E7%95%8C%E6%88%AA%E6%8E%89%22%5D%0A%20%20D%20--%3E%7C%22%E7%95%99%E5%9C%A8%E5%8C%BA%E5%86%85%22%7C%20F%5B%22%E6%95%B0%E5%80%BC%E5%99%AA%E5%A3%B0%E8%A2%AB%E5%BD%93%E6%88%90%E4%BC%98%E5%8A%BF%22%5D%0A%20%20E%20--%3E%20G%5B%22%E6%9C%89%E6%95%88%E6%9B%B4%E6%96%B0%E5%8F%98%E7%A8%80%EF%BC%8C%E7%97%87%E7%8A%B6%E5%83%8F%E7%86%B5%E5%A1%8C%E6%88%96%E5%AD%A6%E4%B9%A0%E7%8E%87%E8%BF%87%E5%A4%A7%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p><span class="marginnote">MoE 路由在量化前后若翻转专家，token 级比率比较的是两个子网络，GSPO 文中的路由挥发在精度不匹配时更早出现。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>评测引擎可以继续量化；训练闭环的 logprob 路径不能。产品 decode 与训练精度不同造成的是<strong>服务 gap</strong>，不是 IS 噪声，应用匹配解码的评测集单独报。本课收束 PPO/GRPO 细节：奖励从哪来、优势怎么造、近端怎么守、系统怎么对齐。下一课开始在没有更多人类比较的前提下扩展监督。</p><p>发布前用同一批 y 对引擎与训练图做 logprob 误差门槛；超阈则禁止把引擎对数概率写进损失。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>引擎与训练图的精度/内核差会造成假 off-policy，clip 命中率异常。</li><li>用训练图重算 logπ 再进比率；引擎 logπ 默认不可信。</li><li>用同一批 y 做对数概率对误差测试，当作发布门槛。</li><li>量化采样可以保留，但必须声明行为策略是否包含量化。</li><li>出处：OpenRLHF / verl 的 logprob 重算实践；Sheng 等 HybridFlow 的多引擎接口；MoE 路由见 Zheng 等 GSPO。</li></ul>',6))])}const D=s(d,[["render",m]]);export{C as __pageData,D as default};
